package com.mygo.music;

import android.app.*;
import android.content.*;
import android.os.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

/** Runs against the actual Android WebView and native network bridge, not a mock JS engine. */
public class PluginInstrumentation extends Instrumentation {
    private String liveResult="";
    private final ArrayList<PluginRuntime> runtimes=new ArrayList<>();
    @Override public void onCreate(Bundle arguments){super.onCreate(arguments);start();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        testLandscape();testAsyncAndPersistence();testNativeNetwork();testOriginalLizhi();testPlaybackPipeline();testBrowserLogin();testLiveSources();
        result.putString("stream","MYGO_TESTS_OK: landscape, ES modules, async result, errors, storage, native fetch, cookies, permissions, original Li Zhi search/stream/like/lyrics, source to Android audio playback, browser login and cookie isolation\n"+liveResult);
        finish(Activity.RESULT_OK,result);
    }catch(Throwable e){result.putString("stream","MYGO_TESTS_FAILED: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}finally{for(PluginRuntime rt:runtimes)rt.dispose();}}
    private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private void testLandscape(){Activity a=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();check(a.getResources().getConfiguration().orientation==2,"landscape did not launch");runOnMainSync(()->checkButtonText(a.getWindow().getDecorView()));runOnMainSync(a::finish);}
    private void checkButtonText(android.view.View view){if(view instanceof android.widget.Button){android.widget.Button button=(android.widget.Button)view;android.graphics.Rect visible=new android.graphics.Rect();if(button.getGlobalVisibleRect(visible)&&visible.height()==button.getHeight()){android.graphics.Paint.FontMetricsInt metrics=button.getPaint().getFontMetricsInt();check(button.getHeight()>=button.getCompoundPaddingTop()+button.getCompoundPaddingBottom()+metrics.descent-metrics.ascent,"clipped button: "+button.getText());}}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)checkButtonText(group.getChildAt(i));}}
    private String read(String name)throws Exception{try(InputStream in=getContext().getAssets().open(name)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
    private PluginRuntime fixture(String id,String source,JSONArray hosts)throws Exception{File dir=new File(getTargetContext().getCacheDir(),id);dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"index.js"))){out.write(source.getBytes("UTF-8"));}try(FileOutputStream out=new FileOutputStream(new File(dir,"plugin.json"))){out.write(new JSONObject().put("id",id).put("main","index.js").put("permissions",new JSONObject().put("network",hosts)).toString().getBytes("UTF-8"));}PluginRuntime rt=new PluginRuntime(getTargetContext(),dir);runtimes.add(rt);return rt;}
    private String call(PluginRuntime rt,String fn,JSONObject args)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] value={null};boolean[] ok={false};rt.call(fn,args,(success,raw)->{ok[0]=success;value[0]=raw;latch.countDown();});check(latch.await(25,TimeUnit.SECONDS),"callback missing: "+fn);check(ok[0],fn+": "+value[0]);return value[0];}
    private void testAsyncAndPersistence()throws Exception{String code="export async function delayed(){await new Promise(r=>setTimeout(r,150));return {ok:42};}export const value=()=>7;export function save(){host.storage.set('session',{cookie:'test'});}export function load(){return host.storage.get('session');}export function error(){throw new Error('expected failure');}";PluginRuntime rt=fixture("async-fixture",code,new JSONArray());check(new JSONObject(call(rt,"delayed",new JSONObject())).getInt("ok")==42,"promise value lost");check("7".equals(call(rt,"value",new JSONObject())),"export const failed");call(rt,"save",new JSONObject());rt.dispose();PluginRuntime fresh=fixture("async-fixture",code,new JSONArray());check(new JSONObject(call(fresh,"load",new JSONObject())).getString("cookie").equals("test"),"session not persisted");CountDownLatch latch=new CountDownLatch(1);fresh.call("error",new JSONObject(),(ok,raw)->{check(!ok&&raw.contains("expected failure"),"error suppressed");latch.countDown();});check(latch.await(10,TimeUnit.SECONDS),"error callback missing");}
    private void testNativeNetwork()throws Exception{ServerSocket server=new ServerSocket(0);Thread worker=new Thread(()->{try(Socket c=server.accept()){BufferedReader br=new BufferedReader(new InputStreamReader(c.getInputStream()));String line;while((line=br.readLine())!=null&&!line.isEmpty()){}byte[] body="{\"ok\":1}".getBytes("UTF-8");c.getOutputStream().write(("HTTP/1.1 200 OK\r\nContent-Length: "+body.length+"\r\nSet-Cookie: a=1; Path=/\r\nSet-Cookie: b=2; Path=/\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));c.getOutputStream().write(body);}catch(Exception ignored){}});worker.start();getTargetContext().getSharedPreferences("library",0).edit().putBoolean("plugin_network_network-fixture",true).commit();PluginRuntime rt=fixture("network-fixture","export async function probe({url}){const r=await fetch(url);return {body:await r.json(),cookies:r.headers.getSetCookie()};}export async function denied(){try{await fetch('http://localhost:1/');return false;}catch(e){return e.message;}}",new JSONArray().put("127.0.0.1"));JSONObject answer=new JSONObject(call(rt,"probe",new JSONObject().put("url","http://127.0.0.1:"+server.getLocalPort()+"/")));check(answer.getJSONObject("body").getInt("ok")==1,"fetch body failed");check(answer.getJSONArray("cookies").length()==2,"cookies lost");check(call(rt,"denied",new JSONObject()).contains("未声明"),"host permission bypass");server.close();check(!PluginRuntime.hostMatches("evil-example.com","*.example.com"),"unsafe wildcard");}
    private void testPlaybackPipeline()throws Exception{
        ServerSocket server=new ServerSocket(0);byte[] wav=new byte[80044];java.nio.ByteBuffer buf=java.nio.ByteBuffer.wrap(wav).order(java.nio.ByteOrder.LITTLE_ENDIAN);buf.put("RIFF".getBytes("US-ASCII")).putInt(wav.length-8).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)1).putShort((short)1).putInt(8000).putInt(16000).putShort((short)2).putShort((short)16).put("data".getBytes("US-ASCII")).putInt(wav.length-44);
        Thread worker=new Thread(()->{while(!server.isClosed()){try(Socket c=server.accept()){BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream()));String line;while((line=r.readLine())!=null&&!line.isEmpty()){}android.os.SystemClock.sleep(700);c.getOutputStream().write(("HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\nContent-Length: "+wav.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));c.getOutputStream().write(wav);}catch(Exception ignored){}}});worker.setDaemon(true);worker.start();
        File dir=new File(getTargetContext().getFilesDir(),"plugins/playback-fixture");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"plugin.json"))){out.write("{\"id\":\"playback-fixture\",\"name\":\"Playback Test\",\"main\":\"index.js\"}".getBytes("UTF-8"));}try(FileOutputStream out=new FileOutputStream(new File(dir,"index.js"))){out.write(("export async function stream(){await new Promise(r=>setTimeout(r,80));return {url:'http://127.0.0.1:"+server.getLocalPort()+"/test.wav'};}").getBytes("UTF-8"));}
        Activity a=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();java.lang.reflect.Method add=MainActivity.class.getDeclaredMethod("addRemote",android.net.Uri.class,String.class,String.class);add.setAccessible(true);java.lang.reflect.Method play=MainActivity.class.getDeclaredMethod("playIndex",int.class);play.setAccessible(true);java.lang.reflect.Field tracks=MainActivity.class.getDeclaredField("tracks"),player=MainActivity.class.getDeclaredField("player");tracks.setAccessible(true);player.setAccessible(true);
        runOnMainSync(()->{try{add.invoke(a,android.net.Uri.parse("plugin://playback-fixture?id=test"),"Playback Test","");play.invoke(a,((java.util.List)tracks.get(a)).size()-1);}catch(Exception e){throw new RuntimeException(e);}});
        boolean[] playing={false};long deadline=android.os.SystemClock.elapsedRealtime()+15000;while(!playing[0]&&android.os.SystemClock.elapsedRealtime()<deadline){runOnMainSync(()->{try{android.media.MediaPlayer mp=(android.media.MediaPlayer)player.get(a);playing[0]=mp!=null&&mp.isPlaying()&&mp.getCurrentPosition()>50;}catch(Exception ignored){}});android.os.SystemClock.sleep(100);}check(playing[0],"initial source playback failed");playing[0]=false;runOnMainSync(()->{try{play.invoke(a,((java.util.List)tracks.get(a)).size()-1);}catch(Exception e){throw new RuntimeException(e);}});deadline=android.os.SystemClock.elapsedRealtime()+15000;while(!playing[0]&&android.os.SystemClock.elapsedRealtime()<deadline){runOnMainSync(()->{try{android.media.MediaPlayer mp=(android.media.MediaPlayer)player.get(a);playing[0]=mp!=null&&mp.isPlaying()&&mp.getCurrentPosition()>50;}catch(Exception ignored){}});android.os.SystemClock.sleep(100);}boolean[] titleVisible={false};runOnMainSync(()->{try{java.lang.reflect.Field field=MainActivity.class.getDeclaredField("landscapeGrid");field.setAccessible(true);android.widget.LinearLayout grid=(android.widget.LinearLayout)field.get(a);android.view.View title=((android.widget.LinearLayout)((android.widget.LinearLayout)grid.getChildAt(0)).getChildAt(0)).getChildAt(1);android.graphics.Rect rect=new android.graphics.Rect();titleVisible[0]=title.getGlobalVisibleRect(rect)&&rect.height()>=title.getHeight();}catch(Exception ignored){}});runOnMainSync(()->{try{android.media.MediaPlayer mp=(android.media.MediaPlayer)player.get(a);if(mp!=null)mp.pause();}catch(Exception ignored){}a.finish();});server.close();for(File f:dir.listFiles())f.delete();dir.delete();check(playing[0],"source did not reach actual Android audio playback");check(titleVisible[0],"landscape toolbar clipped song title");
    }
    private void testBrowserLogin()throws Exception{
        ServerSocket server=new ServerSocket(0);Thread worker=new Thread(()->{try(Socket c=server.accept()){BufferedReader reader=new BufferedReader(new InputStreamReader(c.getInputStream()));String line;while((line=reader.readLine())!=null&&!line.isEmpty()){}byte[] body="<html><body>Test login completed</body></html>".getBytes("UTF-8");c.getOutputStream().write(("HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nSet-Cookie: session_token=fixture; Path=/; HttpOnly\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));c.getOutputStream().write(body);}catch(Exception ignored){}});worker.setDaemon(true);worker.start();String url="http://127.0.0.1:"+server.getLocalPort()+"/";fixture("login-fixture","export async function signIn({url}){const session=await host.webSignIn({url,cookiesOf:url,until:['session_token']});host.storage.set('session',session);return session;}export function saved(){return host.storage.get('session');}",new JSONArray().put("127.0.0.1")).dispose();getTargetContext().getSharedPreferences("library",0).edit().putBoolean("plugin_network_login-fixture",true).commit();Activity a=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();PluginRuntime rt=new PluginRuntime(a,new File(getTargetContext().getCacheDir(),"login-fixture"));runtimes.add(rt);try{String answer=call(rt,"signIn",new JSONObject().put("url",url));check(new JSONObject(answer).getString("cookie").contains("session_token=fixture"),"browser cookie not returned");check(call(rt,"saved",new JSONObject()).contains("session_token=fixture"),"browser session not persisted");String[] cookie={null};runOnMainSync(()->cookie[0]=android.webkit.CookieManager.getInstance().getCookie(url));check(cookie[0]==null||cookie[0].isEmpty(),"temporary browser cookie leaked");}finally{rt.dispose();runOnMainSync(a::finish);server.close();}
    }
    private void testLiveSources(){
        PluginManager manager=new PluginManager(getTargetContext());try{
            CountDownLatch installed=new CountDownLatch(1);boolean[] success={false};String[] message={""};manager.installFromGitHub("djyde/mygo-lizhi",(ok,raw)->{success[0]=ok;message[0]=raw;installed.countDown();});check(installed.await(100,TimeUnit.SECONDS),"live install timed out");check(success[0],message[0]);getTargetContext().getSharedPreferences("library",0).edit().putBoolean("plugin_network_lizhi",true).commit();CountDownLatch searched=new CountDownLatch(1);String[] result={""};manager.searchSource("lizhi","山阴路",(ok,raw)->{success[0]=ok;result[0]=raw;searched.countDown();});check(searched.await(60,TimeUnit.SECONDS),"live search timed out");check(success[0],result[0]);JSONArray tracks=new JSONObject(result[0]).getJSONArray("tracks");check(tracks.length()>0,"live catalog empty");CountDownLatch resolved=new CountDownLatch(1);manager.export("lizhi","stream",new JSONObject().put("id",tracks.getJSONObject(0).getString("id")),(ok,raw)->{success[0]=ok;result[0]=raw;resolved.countDown();});check(resolved.await(30,TimeUnit.SECONDS),"live stream timed out");check(success[0]&&new JSONObject(result[0]).has("url"),result[0]);JSONObject audio=new JSONObject(result[0]);HttpURLConnection connection=(HttpURLConnection)new URL(audio.getString("url")).openConnection();connection.setRequestProperty("Range","bytes=0-127");connection.setConnectTimeout(12000);connection.setReadTimeout(12000);try{check(connection.getResponseCode()/100==2,"live audio HTTP "+connection.getResponseCode());String type=connection.getContentType();check(type==null||!type.contains("text/html"),"live audio was HTML");try(InputStream in=connection.getInputStream()){check(in.read(new byte[128])>15,"live audio empty");}}finally{connection.disconnect();}liveResult+="LIVE_LIZHI_OK: real GitHub install, search, stream, audio bytes\n";
        }catch(Throwable e){liveResult+="LIVE_LIZHI_UNVERIFIED: "+e.toString()+"\n";}finally{runOnMainSync(manager::close);}
        try{getTargetContext().getSharedPreferences("library",0).edit().putBoolean("plugin_network_netease-live",true).commit();PluginRuntime rt=fixture("netease-live",read("netease.js"),new JSONArray().put("music.163.com").put("interfacepc.music.163.com"));JSONObject search=new JSONObject(call(rt,"search",new JSONObject().put("query","晴天").put("kind","tracks")));check(search.getJSONArray("tracks").length()>0,"NetEase returned no tracks");liveResult+="LIVE_NETEASE_OK: original ES module, real API search\n";}catch(Throwable e){liveResult+="LIVE_NETEASE_UNVERIFIED: "+e.toString()+"\n";}
    }
    private void testOriginalLizhi()throws Exception{String source=read("lizhi.js");JSONArray files=new JSONArray().put(new JSONObject().put("path","audio/test/01-test.mp3").put("size",12345));getTargetContext().getSharedPreferences("plugin_data_lizhi-test",0).edit().putString("catalog",new JSONObject().put("time",System.currentTimeMillis()).put("files",files).toString()).putString("lyrics:audio/test/01-test.mp3",new JSONObject().put("lrc","[00:01.00]test").toString()).commit();PluginRuntime rt=fixture("lizhi-test",source,new JSONArray());JSONObject search=new JSONObject(call(rt,"search",new JSONObject().put("query","test").put("kind","tracks")));check(search.getJSONArray("tracks").length()==1,"original plugin search failed");JSONObject stream=new JSONObject(call(rt,"stream",new JSONObject().put("id","audio/test/01-test.mp3")));check(stream.getString("url").endsWith("audio/test/01-test.mp3"),"original stream returned wrong URL");check(!stream.getString("url").contains("/blob/"),"web page mistaken for stream");call(rt,"like",new JSONObject().put("id","audio/test/01-test.mp3").put("on",true));check(new JSONObject(call(rt,"liked",new JSONObject())).getJSONArray("tracks").length()==1,"original likes failed");check(new JSONObject(call(rt,"lyrics",new JSONObject().put("id","audio/test/01-test.mp3"))).getString("lrc").contains("test"),"original lyrics failed");check(new JSONObject(call(rt,"album",new JSONObject().put("id","test"))).getJSONArray("tracks").length()==1,"export alias failed");}
}
